	--SELECT NR AS RNO, TOKEN AS VALUE FROM STRING_SPLIT(@TEXT, @DELIMETER)

	INSERT INTO @TV
	SELECT AA.RNO, NAME , VALUE,  T
	FROM (
		SELECT  ROW_NUMBER() OVER (ORDER BY P.parameter_id) AS RNO
 			, p.name, TYPE_NAME(p.user_type_id) AS T
		FROM sys.parameters p
		INNER JOIN sys.objects o ON p.object_id = o.object_id
		WHERE o.type = 'P'  -- P = Stored Procedure
		  AND o.name = @P_PROCEDURE  -- 프로시저 이름 대체
		  --AND SCHEMA_NAME(o.schema_id) = 'dbo'  -- 스키마명도 필요하면 필터
		  ) AA
	INNER JOIN (SELECT NR AS RNO, TOKEN AS VALUE FROM STRING_SPLIT(@TEXT, @DELIMETER)) S  ON S.RNO = AA.RNO	
	ORDER BY S.RNO

	--SELECT * FROM @TV

	SELECT   @P_RESULT =  @P_PROCEDURE + ' ' +  STRING_AGG( CASE WHEN  T IN ('NVARCHAR', 'VARCHAR') THEN '''' +  VALUE + '''' 
					ELSE VALUE END , ',') 
	 FROM @TV

END


